import Foundation
import CoreBluetooth
import Darwin

final class Radio: NSObject, CBCentralManagerDelegate, CBPeripheralDelegate, CBPeripheralManagerDelegate {
    let queue = DispatchQueue(label: "mesh-talk.ble")
    let permit = DispatchSemaphore(value: 0)
    let outputQueue = DispatchQueue(label: "mesh-talk.ble.output")
    let outputSlots = DispatchSemaphore(value: 64)
    let serviceID = CBUUID(string: "AC28D512-96E8-4520-A33A-43C71096A001")
    let rxID = CBUUID(string: "AC28D512-96E8-4520-A33A-43C71096A002")
    let txID = CBUUID(string: "AC28D512-96E8-4520-A33A-43C71096A003")
    let role: String
    var central: CBCentralManager!
    var manager: CBPeripheralManager!
    var peer: CBPeripheral?
    var subscriber: CBCentral?
    var rx: CBCharacteristic?
    var tx: CBMutableCharacteristic?
    var pending: Data?
    var active = true
    var ready = false
    var signalSource: DispatchSourceSignal?

    init(role: String) {
        self.role = role
        super.init()
        signal(SIGINT, SIG_IGN)
        let source = DispatchSource.makeSignalSource(signal: SIGINT, queue: queue)
        source.setEventHandler { self.stop(0, "interrupted") }
        signalSource = source
        source.resume()
        queue.async {
            if role == "central" { self.central = CBCentralManager(delegate: self, queue: self.queue) }
            else { self.manager = CBPeripheralManager(delegate: self, queue: self.queue) }
        }
        // Only this thread waits. A permit represents exactly one available packet slot.
        Thread.detachNewThread {
            while true {
                self.permit.wait()
                var bytes = [UInt8](repeating: 0, count: 20)
                let count = Darwin.read(STDIN_FILENO, &bytes, bytes.count)
                if count < 0 && errno == EINTR { self.permit.signal(); continue }
                let packet = count > 0 ? Data(bytes.prefix(count)) : nil
                self.queue.async {
                    guard self.active else { return }
                    guard let packet else { self.stop(count == 0 ? 0 : 1, "stdin closed"); return }
                    self.pending = packet
                    self.sendPending()
                }
                if count <= 0 { return }
            }
        }
    }
    func log(_ text: String) { FileHandle.standardError.write(Data((text + "\n").utf8)) }
    func stop(_ code: Int32, _ reason: String) {
        guard active else { return }
        active = false
        log(reason)
        central?.stopScan()
        if let peer { central?.cancelPeripheralConnection(peer) }
        manager?.stopAdvertising()
        manager?.removeAllServices()
        exit(code)
    }
    func markReady() {
        guard active, !ready else { return }
        ready = true
        log("ready: \(role)")
        permit.signal()
    }
    func output(_ data: Data) {
        // Never block CoreBluetooth callbacks or signal handling on a pipe write.
        guard !data.isEmpty, data.count <= 20,
              outputSlots.wait(timeout: .now()) == .success else {
            stop(1, "inbound BLE budget exceeded")
            return
        }
        outputQueue.async {
            defer { self.outputSlots.signal() }
            var offset = 0
            data.withUnsafeBytes { bytes in
                while offset < bytes.count {
                    let n = Darwin.write(STDOUT_FILENO, bytes.baseAddress!.advanced(by: offset), bytes.count - offset)
                    if n < 0 && errno == EINTR { continue }
                    if n <= 0 {
                        self.queue.async { self.stop(1, "stdout write failed") }
                        return
                    }
                    offset += n
                }
            }
        }
    }
    func sendPending() {
        guard active, let data = pending else { return }
        if role == "central" {
            guard let peer, let rx else { stop(1, "missing write characteristic"); return }
            peer.writeValue(data, for: rx, type: .withResponse)
        } else if let tx, let subscriber {
            if manager.updateValue(data, for: tx, onSubscribedCentrals: [subscriber]) {
                pending = nil
                permit.signal()
            }
        }
    }
    func centralManagerDidUpdateState(_ central: CBCentralManager) {
        guard active else { return }
        if central.state == .poweredOn { central.scanForPeripherals(withServices: [serviceID]) }
        else if ready || (central.state != .unknown && central.state != .resetting) { stop(1, "Bluetooth unavailable: \(central.state.rawValue)") }
    }
    func centralManager(_ central: CBCentralManager, didDiscover peripheral: CBPeripheral, advertisementData: [String: Any], rssi RSSI: NSNumber) {
        guard active, peer == nil else { return }
        peer = peripheral
        peripheral.delegate = self
        central.stopScan()
        central.connect(peripheral)
    }
    func centralManager(_ central: CBCentralManager, didConnect peripheral: CBPeripheral) {
        guard active else { return }
        peripheral.discoverServices([serviceID])
    }
    func centralManager(_ central: CBCentralManager, didFailToConnect peripheral: CBPeripheral, error: Error?) { stop(1, "connection failed: \(String(describing: error))") }
    func centralManager(_ central: CBCentralManager, didDisconnectPeripheral peripheral: CBPeripheral, error: Error?) { stop(1, "disconnected") }
    func peripheral(_ peripheral: CBPeripheral, didDiscoverServices error: Error?) {
        guard active else { return }
        guard error == nil, let service = peripheral.services?.first(where: { $0.uuid == serviceID }) else { stop(1, "service discovery failed"); return }
        peripheral.discoverCharacteristics([rxID, txID], for: service)
    }
    func peripheral(_ peripheral: CBPeripheral, didDiscoverCharacteristicsFor service: CBService, error: Error?) {
        guard active else { return }
        let chars = service.characteristics ?? []
        guard error == nil, let write = chars.first(where: { $0.uuid == rxID }), write.properties.contains(.write),
              let notify = chars.first(where: { $0.uuid == txID }), notify.properties.contains(.notify) else { stop(1, "characteristic discovery failed"); return }
        rx = write
        peripheral.setNotifyValue(true, for: notify)
    }
    func peripheral(_ peripheral: CBPeripheral, didUpdateNotificationStateFor characteristic: CBCharacteristic, error: Error?) {
        guard active else { return }
        guard error == nil, characteristic.isNotifying else { stop(1, "notification subscription failed"); return }
        markReady()
    }
    func peripheral(_ peripheral: CBPeripheral, didUpdateValueFor characteristic: CBCharacteristic, error: Error?) {
        guard active else { return }
        guard error == nil, let data = characteristic.value else { stop(1, "notification failed"); return }
        output(data)
    }
    func peripheral(_ peripheral: CBPeripheral, didWriteValueFor characteristic: CBCharacteristic, error: Error?) {
        guard active else { return }
        guard error == nil else { stop(1, "BLE write failed"); return }
        pending = nil
        permit.signal()
    }
    func peripheralManagerDidUpdateState(_ peripheral: CBPeripheralManager) {
        guard active else { return }
        if peripheral.state == .poweredOn {
            let service = CBMutableService(type: serviceID, primary: true)
            let receive = CBMutableCharacteristic(type: rxID, properties: [.write], value: nil, permissions: [.writeable])
            let transmit = CBMutableCharacteristic(type: txID, properties: [.notify], value: nil, permissions: [])
            tx = transmit
            service.characteristics = [receive, transmit]
            peripheral.add(service)
        } else if ready || (peripheral.state != .unknown && peripheral.state != .resetting) { stop(1, "Bluetooth unavailable: \(peripheral.state.rawValue)") }
    }
    func peripheralManager(_ peripheral: CBPeripheralManager, didAdd service: CBService, error: Error?) {
        guard active else { return }
        guard error == nil else { stop(1, "service registration failed"); return }
        peripheral.startAdvertising([CBAdvertisementDataServiceUUIDsKey: [serviceID]])
    }
    func peripheralManagerDidStartAdvertising(_ peripheral: CBPeripheralManager, error: Error?) {
        if error != nil { stop(1, "advertising failed") }
    }
    func peripheralManager(_ peripheral: CBPeripheralManager, central: CBCentral, didSubscribeTo characteristic: CBCharacteristic) {
        guard active else { return }
        guard subscriber == nil || subscriber?.identifier == central.identifier else { stop(1, "multiple subscribers are unsupported"); return }
        subscriber = central
        peripheral.stopAdvertising()
        markReady()
    }
    func peripheralManager(_ peripheral: CBPeripheralManager, central: CBCentral, didUnsubscribeFrom characteristic: CBCharacteristic) { stop(1, "subscriber disconnected") }
    func peripheralManagerIsReady(toUpdateSubscribers peripheral: CBPeripheralManager) { sendPending() }
    func peripheralManager(_ peripheral: CBPeripheralManager, didReceiveWrite requests: [CBATTRequest]) {
        guard active else { return }
        for request in requests {
            guard request.characteristic.uuid == rxID, request.offset == 0,
                  subscriber?.identifier == request.central.identifier, let data = request.value, data.count <= 20 else {
                peripheral.respond(to: request, withResult: .unlikelyError)
                continue
            }
            output(data)
            peripheral.respond(to: request, withResult: .success)
        }
    }
}

signal(SIGPIPE, SIG_IGN)
guard CommandLine.arguments.count == 2, ["central", "peripheral"].contains(CommandLine.arguments[1]) else {
    FileHandle.standardError.write(Data("usage: bluetooth-radio central|peripheral\n".utf8))
    exit(2)
}
let radio = Radio(role: CommandLine.arguments[1])
dispatchMain()
# Native Bluetooth transport

Native BLE is an experimental direct-link transport, separate from the released
UDP multicast discovery and TCP node runtime. It is currently a two-host macOS
rehearsal, not an enabled desktop chat feature. It does not interoperate with
Bitchat. Pure PWA peripheral support is outside this capability.

## Ownership and authentication

`transport/ble.rs` owns the bounded session-scoped chunk/byte-stream boundary.
`SecureChannel` remains the owner of Noise XX and device identity binding. Native
adapters must reserve inbound capacity before copying callback data and close a
link on budget exhaustion; callbacks must never wait for a consumer or hold node
locks. Shutdown revokes queued data as well as future callbacks. The byte stream's
flush acknowledges queue admission, not radio acknowledgment or durable delivery.

`src-tauri/examples/bluetooth-radio.swift` owns a single CoreBluetooth central or
peripheral connection for the rehearsal. GATT writes use response acknowledgment;
notifications wait for native readiness after backpressure. Chunks are at most
20 bytes. One pending outbound chunk and 64 inbound output slots bound buffering.
A dedicated stdout writer prevents a blocked consumer from freezing Bluetooth
callbacks or signal handling. Disconnect, power loss and malformed or excessive
input fail the process; the caller must start a new session to retry.

`bluetooth-rehearsal` owns the explicit process lifecycle, two-minute deadline,
pre-exchanged public-key pinning and encrypted echo. The helper sees encrypted
Noise bytes, not chat plaintext. Its process and streams are retired on failure,
Ctrl-C or completion. Test text is limited to 4096 bytes and is held in memory;
an echo is not a persisted message, account proof, read receipt or delivery claim.
Use dedicated rehearsal identities, not production account keystores.

## Two-host macOS rehearsal

Build on each host from the repository root (Xcode Command Line Tools required):

```sh
mkdir -p tmp/bluetooth
swiftc src-tauri/examples/bluetooth-radio.swift -o tmp/bluetooth/radio \
  -Xlinker -sectcreate -Xlinker __TEXT -Xlinker __info_plist \
  -Xlinker src-tauri/examples/bluetooth-radio.plist
cargo build -p mesh-talk-core --example bluetooth-rehearsal
```

Create a private password file at `tmp/bluetooth/password` using a local editor,
then run `chmod 600 tmp/bluetooth/password`. Create and print each host's dedicated
public identity (this command does not start Bluetooth):

```sh
cargo run -p mesh-talk-core --example bluetooth-rehearsal -- \
  --keystore tmp/bluetooth/identity --password-file tmp/bluetooth/password --identity
```

Exchange the printed public keys through an authenticated out-of-band channel.
On host A, run the following with host B's key; on host B use `--role central`
and host A's key. Allow the operating system's Bluetooth permission request.

```sh
cargo run -p mesh-talk-core --example bluetooth-rehearsal -- \
  --keystore tmp/bluetooth/identity --password-file tmp/bluetooth/password \
  --radio tmp/bluetooth/radio --role peripheral --peer PEER_PUBLIC_KEYS
```

